PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX ddo: <http://purl.obolibrary.org/obo/DDO.owl#>
PREFIX ftdm: <https://bioportal.bioontology.org/ontologies/FTDM.owl#>
PREFIX ftdm2: <https://bioportal.bioontology.org/ontologies/FTDM/>
PREFIX fasto: <https://bioportal.bioontology.org/ontologies/FASTO/>
PREFIX fhir: <http://hl7.org/fhir/>
PREFIX ssn: <http://www.w3.org/ns/ssn/>
PREFIX ontofood: <http://www.owl-ontologies.com/OntoFood.owl#>
PREFIX oae: <http://purl.obolibrary.org/obo/OAE_>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?patient ?hypoglycemiaHistory ?carePlan ?isCurrent WHERE {
  ?patient rdf:type ddo:DDO_0000111 .
  OPTIONAL { ?patient ftdm2:hasHistoryOfHypoglycemia ?hypoglycemiaHistory . }
  OPTIONAL {
    ?carePlan rdf:type ftdm:DMTO_0000044 ;
              <http://hl7.org/fhir/CarePlan.subject> ?patient .
    OPTIONAL { ?carePlan fasto:isCurrent ?isCurrent . }
  }
}

